import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ──────────────────────────────────────────────────────────────────────
  // 1. SETUP: Geometry, Materials, Mesh
  // ──────────────────────────────────────────────────────────────────────

  // Tessellated plane for displacement
  const geometry = new THREE.PlaneGeometry(2.5, 0.25, 64, 64);
  const group = new THREE.Group();

  // Load textures
  const textures = {};
  let diffuseLoaded = false;
  let depthLoaded = false;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    textures.diffuse = tex;
    textures.diffuse.colorSpace = THREE.SRGBColorSpace;
    diffuseLoaded = true;
    if (material) material.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    textures.depth = tex;
    textures.depth.colorSpace = THREE.LinearSRGBColorSpace;
    depthLoaded = true;
    if (material) material.needsUpdate = true;
  });

  // TSL Material with displacement
  const displacementAmount = uniform(0.12);
  const displacementStrength = uniform(1.0);

  const material = new MeshStandardNodeMaterial({
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.2,
  });

  // Position node for displacement
  const positionNode = material.positionNode
    ? material.positionNode
    : uniform(vec3(0, 0, 0));

  const depthSampler = texture(
    uniform(THREE.Texture, () => textures.depth || new THREE.Texture()),
    uv()
  );

  // Displace vertices along normal by depth map
  material.positionNode = positionNode.add(
    depthSampler
      .r.mul(displacementAmount)
      .mul(displacementStrength)
      .mul(uniform(vec3(0, 0, 1)))
  );

  // Diffuse color
  material.colorNode = texture(
    uniform(THREE.Texture, () => textures.diffuse || new THREE.Texture()),
    uv()
  );

  material.side = THREE.DoubleSide;
  material.wireframe = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.scale.set(1, 1, 1);
  group.add(mesh);

  // ──────────────────────────────────────────────────────────────────────
  // 2. LIGHTING: Rim light for accent accent hue on dark stage
  // ──────────────────────────────────────────────────────────────────────

  const rimLight = new THREE.PointLight(0xff2a38, 0.8, 3.0);
  rimLight.position.set(-1.5, 0.3, 1.2);
  group.add(rimLight);

  // ──────────────────────────────────────────────────────────────────────
  // 3. INTERACTION: Hover (rise-in, subtle 0.15 units), Click (emit event)
  // ──────────────────────────────────────────────────────────────────────

  let hoverTimeline = null;
  let clickTimeline = null;

  const handlers = {
    onHover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onHoverOut: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: -0.2,
        duration: 0.5,
        ease: 'power2.out',
      });
    },
    onClick: () => {
      if (clickTimeline) clickTimeline.kill();
      clickTimeline = gsap.timeline();
      clickTimeline.to(
        group.scale,
        { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' },
        0
      );
      clickTimeline.to(
        group.scale,
        { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' },
        0.12
      );

      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  group.userData.handlers = handlers;

  // ──────────────────────────────────────────────────────────────────────
  // 4. PARALLAX EFFECT: Subtle mouse-driven vertical shift
  // ──────────────────────────────────────────────────────────────────────

  let parallaxTimeline = null;
  const parallaxStrength = 0.08; // subtle shift in z for depth illusion

  group.userData.onMouseMove = (clientX, clientY, screenWidth, screenHeight) => {
    const normalizedX = (clientX / screenWidth) * 2 - 1; // [-1, 1]
    const normalizedY = -(clientY / screenHeight) * 2 + 1; // [-1, 1]

    // Parallax shift based on mouse position
    const targetZ = normalizedX * parallaxStrength;

    if (parallaxTimeline) parallaxTimeline.kill();
    parallaxTimeline = gsap.to(group.position, {
      z: targetZ,
      duration: 0.6,
      ease: 'power2.out',
    });
  };

  // ──────────────────────────────────────────────────────────────────────
  // 5. CLEANUP
  // ──────────────────────────────────────────────────────────────────────

  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
    if (parallaxTimeline) parallaxTimeline.kill();
    geometry.dispose();
    material.dispose();
    rimLight.dispose();
  };

  return group;
}
